"""Build the services-only FBS website from editable content and local images."""
from pathlib import Path
import json,html,os,shutil,re
ROOT=Path(__file__).parent;OUT=ROOT/'dist'
S=json.loads((ROOT/'content/site.json').read_text());GUIDES=json.loads((ROOT/'content/guides.json').read_text());IMAGES=json.loads((ROOT/'content/images.json').read_text())
ORIGIN=os.environ.get('FBS_SITE_ORIGIN','https://fbs-flooring-redesign.dave-smith-tripadvis.chatgpt.site').rstrip('/')
STAGING=os.environ.get('FBS_STAGING','1')!='0'
# Output is reproducible; remove obsolete retail routes from the previous version.
if OUT.exists():shutil.rmtree(OUT)
shutil.copytree(ROOT/'assets',OUT/'assets')
CSS=(ROOT/'assets/site.css').read_text();JS=(ROOT/'assets/site.js').read_text()+'\n'+(ROOT/'assets/motion.js').read_text();PAGES=[]
e=lambda value:html.escape(str(value or ''),quote=True)
ARROW='<span aria-hidden="true">↗</span>'
def brand():return '<a class="brand" href="/" aria-label="FBS Flooring home"><b>FBS</b><span>FLOORING<br>SERVICES</span></a>'
def button(label,url,style=''):return f'<a class="button {style}" href="{e(url)}">{e(label)} {ARROW}</a>'
def textlink(label,url):return f'<a class="text-link" href="{e(url)}">{e(label)} {ARROW}</a>'
def image(key,alt='',eager=False):
 record=IMAGES[key];return f'<img src="{record["src"]}" data-fallback="{e(record["source"])}" alt="{e(alt)}" loading="{"eager" if eager else "lazy"}" decoding="async"'+(' fetchpriority="high"' if eager else '')+'>'
def crumbs(label,parent=None):return '<nav class="breadcrumbs" aria-label="Breadcrumb"><a href="/">Home</a><span aria-hidden="true">/</span>'+(f'<a href="{parent[1]}">{parent[0]}</a><span aria-hidden="true">/</span>' if parent else '')+f'<span aria-current="page">{e(label)}</span></nav>'
def heading(title,desc='',eyebrow=''):return f'<div class="page-heading"><span class="eyebrow">{e(eyebrow)}</span><h1>{title}</h1>'+(f'<p>{e(desc)}</p>' if desc else '')+'</div>'
def header():
 nav=''.join(f'<a href="{p}">{label}</a>' for p,label in [('/services/','Our services'),('/how-it-works/','How it works'),('/gallery/','Inspiration'),('/blog/','Advice'),('/about-us/','About FBS')])
 return f'<a class="skip" href="#main">Skip to content</a><div class="topline"><div class="wrap"><span>{e(S["announcement"])}</span><a href="tel:+353830441400">Talk to FBS · {e(S["phone"])}</a></div></div><header class="site-header"><div class="wrap nav-row">{brand()}<nav class="nav" aria-label="Main navigation">{nav}</nav><div class="nav-tools">{button("Book a consultation","/contact-us/#quote")}<button class="icon-button nav-mobile-toggle" id="mobile-trigger" aria-expanded="false" aria-controls="mobile-menu" aria-label="Open navigation"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 7h18M3 12h18M3 17h18"/></svg></button></div></div><nav id="mobile-menu" class="mobile-menu" aria-label="Mobile navigation" hidden>{nav}<a href="/contact-us/#quote">Book a consultation</a><a href="tel:+353830441400">Call FBS</a></nav></header>'
def footer():
 return f'''<section class="cta-band"><div class="wrap cta-inner"><div><span class="eyebrow" style="color:#c4cdbd">Your space. Your next step.</span><h2>Let’s talk about<br>your floor.</h2><p>A room refresh or a whole new home. Tell us what you have in mind and start with a free consultation.</p></div>{button('Book a free consultation','/contact-us/#quote','light')}</div></section><footer class="footer"><div class="wrap"><div class="footer-grid"><div>{brand()}<p>Consultation, measuring and professional floor fitting. Based in Dublin, working with you to plan the details.</p></div><div><h3>Our services</h3><a href="/services/home-consultation/">Free home consultation</a><a href="/services/floor-fitting/">Professional fitting</a><a href="/services/new-homes-renovations/">New homes & renovations</a><a href="/services/">All services</a></div><div><h3>Your project</h3><a href="/how-it-works/">How it works</a><a href="/flooring-planner/">Room area planner</a><a href="/blog/">Preparation & advice</a><a href="/gallery/">Interior inspiration</a><a href="/faqs/">Common questions</a></div><div><h3>Speak to FBS</h3><a href="tel:+353830441400">{e(S['phone'])}</a><a href="mailto:info@fbsflooring.ie">{e(S['email'])}</a><address>{e(S['address'])}</address><a href="/contact-us/">Contact details & enquiry</a></div></div><div class="footer-bottom"><span>© 2026 FBS Flooring</span><div><a href="/privacy-policy/">Privacy</a><a href="/cookie-policy/">Cookies</a><a href="/sitemap/">Sitemap</a></div></div></div></footer><div class="mobile-contact">{button('Call FBS','tel:+353830441400','outline')}{button('Free consultation','/contact-us/#quote')}</div>'''
def write(path,title,desc,body,schema=None):
 target=OUT/('index.html' if path=='/' else path.strip('/')+'/index.html');target.parent.mkdir(parents=True,exist_ok=True)
 graph=[{'@context':'https://schema.org','@type':'HomeAndConstructionBusiness','name':S['name'],'url':ORIGIN,'telephone':'+353830441400','email':S['email'],'address':{'@type':'PostalAddress','streetAddress':'Unit J2, Malahide Road Industrial Estate','addressLocality':'Coolock','addressRegion':'Dublin','postalCode':'D17 FR58','addressCountry':'IE'}}]
 if schema:graph.append(schema)
 target.write_text(f'''<!doctype html><html lang="en-IE"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | FBS Flooring</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{ORIGIN}{path}"><meta name="robots" content="{'noindex,nofollow' if STAGING else 'index,follow'}"><meta name="theme-color" content="#26362e"><meta property="og:title" content="{e(title)} | FBS Flooring"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{ORIGIN}{path}"><meta property="og:type" content="website"><link rel="icon" type="image/svg+xml" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='5' fill='%2326362e'/%3E%3Cpath d='M8 23V9h15M8 15h11' stroke='%23dbb77c' stroke-width='3' fill='none'/%3E%3C/svg%3E"><style>{CSS}</style><script>document.addEventListener('error',function(ev){{var im=ev.target;if(im.tagName==='IMG'&&im.dataset.fallback&&!im.dataset.retried){{im.dataset.retried='true';im.src=im.dataset.fallback;}}}},true);</script><script type="application/ld+json">{json.dumps(graph).replace('<','\\u003c')}</script></head><body>{header()}<main id="main">{body}</main>{footer()}<script>{JS}</script></body></html>''')
 PAGES.append({'path':path,'title':title,'description':desc})
def service_cards():return '<div class="cards" data-service-cards>'+''.join(f'<article class="service-card"><span class="number">0{i+1}</span><h3>{e(s["title"])}</h3><p>{e(s["summary"])}</p>{textlink("Explore the service","/services/"+s["slug"]+"/")}</article>' for i,s in enumerate(S['services']))+'</div>'
def guide_card(g):return f'<article class="article-card" data-article data-title="{e(g["title"].lower())}" data-category="{e(g["category"])}"><a class="card-photo" href="/{g["slug"]}/">{image(g["image"],"Flooring planning illustration")}</a><span class="meta">{e(g["category"])}</span><h3><a href="/{g["slug"]}/">{e(g["title"])}</a></h3><p>{e(g["summary"])}</p>{textlink("Read the guide","/"+g["slug"]+"/")}</article>'
FAQ=[('What services does FBS offer?','FBS offers free home consultations, measuring and advice, and professional fitting in collaboration with fitting specialists. Discuss your new-home, renovation, residential or commercial project with the team.'),('Is the home consultation free?','Yes. FBS’s home consultation is free. Fitting and any other agreed project work are quoted separately.'),('Can I ask about fitting flooring I already have?','Yes. Send the exact flooring specification, room details and any installation instructions. FBS will review the fitting requirements and discuss suitability before agreeing the work.'),('Where do you work?','FBS is based in Coolock, Dublin. Share your town or Eircode so the team can confirm whether they can arrange a consultation or fitting for your location.'),('How much does fitting cost?','The quotation depends on your rooms, floor area, existing surface and agreed fitting scope. Contact FBS with your project details; no fixed fitting rate is published on this website.'),('What should I prepare before getting in touch?','Room photographs, approximate measurements and a floor plan are useful. Share your timing and the flooring specification if you already have it. You can still get in touch if you have not measured yet.'),('Do you work on business premises?','FBS’s published information includes residential and commercial projects. Describe the space, how it is used and the access requirements so the fitting scope can be discussed.'),('Does an enquiry confirm an appointment?','No. FBS will need to agree the location, requirements and appointment or fitting date with you. Sending a message starts that conversation.')]
def faqs(items):return '<div class="faq">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in items)+'</div>'
steps=[('Tell us about your space','Share the rooms, location and what you would like to do.'),('Start with a home consultation','Discuss measurements, the existing surface and your priorities.'),('Agree the fitting scope','Review the work, preparation, finishing details and quotation.'),('Plan the fitting','Confirm room readiness, access and timing with the team.')]
def step_list():return '<ol class="step-list">'+''.join(f'<li><div><strong>{e(t)}</strong><span>{e(d)}</span></div></li>' for t,d in steps)+'</ol>'
home=f'''<section class="hero"><div class="hero-copy"><span class="eyebrow">FBS Flooring · Dublin</span><h1>Expert fitting.<br>A home that feels<br><em>finished.</em></h1><p>{e(S['intro'])}</p><div class="actions">{button('Book a free consultation','/contact-us/#quote')}{textlink('Explore our services','/services/')}</div></div><div class="hero-visual">{image('hero','Bright interior with herringbone flooring, shown for inspiration',True)}<span class="photo-caption">Interior inspiration · FBS website imagery</span></div></section><div class="service-strip"><div class="wrap strip-inner"><span><i class="dot"></i> Free home consultations</span><span><i class="dot"></i> Measuring & practical advice</span><span><i class="dot"></i> Professional fitting</span><span><i class="dot"></i> New homes & renovations</span></div></div><section class="section"><div class="wrap"><div class="section-head"><div><span class="eyebrow">The right start. A considered finish.</span><h2>Flooring services,<br>built around your space.</h2><p>Whether you’re updating one room or planning a whole home, start with the help your project needs.</p></div>{textlink('All services','/services/')}</div>{service_cards()}</div></section><section class="section soft"><div class="wrap split"><div class="split-photo">{image('home','Room with fitted timber flooring, used as an illustration')}<span class="photo-caption">Illustrative FBS website imagery</span></div><div class="split-copy"><span class="eyebrow">From first conversation to fitting</span><h2>A clear plan.<br>Every step of the way.</h2><p>You bring the ideas. We help you work through the measurements, practical details and fitting requirements.</p>{step_list()}<div class="actions">{textlink('See how it works','/how-it-works/')}</div></div></div></section><section class="section"><div class="wrap statement"><span class="eyebrow">Room for your ideas</span><h2>A new beginning.<br>A familiar space, <em>reimagined.</em></h2><p class="muted">Take a little inspiration, then talk to FBS about the fitting your own space needs.</p></div><div class="wrap" style="margin-top:50px"><div class="inspiration-grid"><figure>{image('hero','Herringbone floor in a bright open living space')}<figcaption>Pattern & warmth · Interior inspiration</figcaption></figure><figure>{image('kitchen','Timber floor in a white kitchen')}<figcaption>Light & texture · Interior inspiration</figcaption></figure></div><p class="media-note">Lifestyle imagery published on the FBS website. These interiors are shown for inspiration and are not presented as completed FBS installations.</p>{textlink('Explore interior inspiration','/gallery/')}</div></section><section class="section soft"><div class="wrap"><div class="section-head"><div><span class="eyebrow">Before the first board</span><h2>A little preparation.<br>A clearer project.</h2></div>{textlink('All advice & guides','/blog/')}</div><div class="cards" data-guide-cards>{''.join(guide_card(g) for g in GUIDES[:3])}</div></div></section><section class="section"><div class="wrap"><div class="statement"><span class="eyebrow">Useful to know</span><h2>Your questions, answered.</h2></div>{faqs(FAQ[:4])}<div class="actions" style="justify-content:center">{textlink('More questions & answers','/faqs/')}</div></div></section>'''
write('/','Flooring Consultation & Professional Fitting in Dublin',S['intro'],home)
body=f'<div class="wrap">{crumbs("Our services")}{heading("Good advice.<br><em>Careful fitting.</em>","Start with your rooms and your plans. FBS helps you work through the practical details and arrange professional fitting.","Our services")}{service_cards()}</div><section class="section"><div class="wrap split"><div class="split-copy"><span class="eyebrow">Homes & businesses</span><h2>Tell us what your<br>project needs.</h2><p>FBS’s services cover residential and commercial projects. Share the room layout, existing surface, access requirements and your preferred timing.</p><p>Already have your flooring? Send the specification so the fitting requirements can be reviewed.</p><div class="actions">{button("Discuss my project","/contact-us/#quote")}</div></div><div class="split-photo">{image("consultation","Bright interior showing a floor installation, used as an illustration")}<span class="photo-caption">Illustrative FBS website imagery</span></div></div></section><section class="section soft"><div class="wrap statement"><h2>Start with a conversation.</h2><p class="muted">Your free consultation helps you understand the next step. The work, quotation and timing are agreed for your project.</p><div class="actions" style="justify-content:center">{textlink("How it works","/how-it-works/")}</div></div></section>'
write('/services/','Flooring Services in Dublin','Free home consultations, measurements, practical advice and professional fitting for new homes, renovations and business spaces.',body)
for s in S['services']:
 body=f'<div class="wrap service-details">{crumbs(s["title"],("Our services","/services/"))}{heading(e(s["title"]),s["intro"],s["short"])}<div class="split"><div class="split-photo">{image(s["image"],"Flooring interior illustration from the FBS website")}<span class="photo-caption">Illustrative FBS website imagery</span></div><div class="split-copy"><h2>What we’ll discuss.</h2><ol class="step-list">'+''.join(f'<li><div><strong>{e(t)}</strong><span>{e(d)}</span></div></li>' for t,d in s['steps'])+f'</ol><p class="form-note">{e(s["note"])}</p><div class="actions">{button("Talk to FBS","/contact-us/?service="+s["slug"]+"#quote")}</div></div></div></div><section class="section soft"><div class="wrap"><div class="section-head"><h2>Prepare for the next step.</h2>{textlink("All practical advice","/blog/")}</div><div class="cards">'+''.join(guide_card(g) for g in GUIDES[:3])+'</div></div></section>'
 write('/services/'+s['slug']+'/',s['title']+' in Dublin',s['summary'],body,{'@context':'https://schema.org','@type':'Service','name':s['title'],'description':s['summary'],'provider':{'@type':'Organization','name':'FBS Flooring'}})
write('/how-it-works/','How Your Flooring Project Works','Understand the FBS consultation and fitting process, from room details and measurements to an agreed scope and fitting date.',f'<div class="wrap">{crumbs("How it works")}{heading("First the plan.<br>Then the <em>fitting.</em>","Clear conversations make a better starting point. Here’s how to begin your project with FBS.","How it works")}<div class="split" style="padding-bottom:70px"><div class="split-copy">{step_list()}<p class="form-note">Appointments and fitting dates are agreed directly with FBS. An enquiry is the first step.</p>{button("Start my project","/contact-us/#quote")}</div><div class="split-photo">{image("preparation","Flooring materials in a room before fitting, used as an illustration")}<span class="photo-caption">Illustrative FBS website imagery</span></div></div></div><section class="section soft"><div class="wrap"><div class="statement"><h2>A little information<br>goes a long way.</h2><p class="muted">Room photos, a floor plan and approximate dimensions help us understand your project. If you already have flooring, share its specification too.</p><div class="actions" style="justify-content:center">{textlink("Use the room area planner","/flooring-planner/")}</div></div></div></section>')
write('/about-us/','About FBS Flooring Services','Meet FBS Flooring: consultation and professional fitting for homes and businesses from its base in Coolock, Dublin.',f'<div class="wrap">{crumbs("About FBS")}{heading("Your home.<br>A thoughtful <em>approach.</em>","Flooring services from our base in Coolock, Dublin.","About FBS")}<div class="split" style="padding-bottom:80px"><div class="split-photo">{image("kitchen","Warm timber floor in a kitchen, shown for inspiration")}<span class="photo-caption">Interior inspiration</span></div><div class="split-copy"><h2>Good work starts<br>with listening.</h2><p>FBS Flooring is led by owner Ilir Sulaj. The team works with fitting specialists to help people plan and carry out flooring projects.</p><p>From a home consultation and measurements to the fitting details, the conversation starts with your space and what you need from it.</p><p>Moving into a new home, renovating a room or planning a business space? Tell FBS about the project and discuss the next step.</p><div class="actions">{button("Speak to FBS","/contact-us/#quote")}</div></div></div></div>')
write('/faqs/','Flooring Consultation & Fitting Questions','Answers about free consultations, fitting enquiries, project preparation, locations and quotations from FBS.',f'<div class="wrap">{crumbs("Common questions")}{heading("A few things<br>you might be <em>wondering.</em>","Practical answers before you get in touch.","Common questions")}{faqs(FAQ)}</div><div style="height:75px"></div>')
contact=f'''<div class="wrap">{crumbs('Contact FBS')}{heading('Let’s start<br>with <em>your space.</em>','Tell us about your rooms and your plans. Arrange a free home consultation or discuss the fitting you need.','Contact FBS')}<div class="contact-grid"><section class="contact-copy"><h2>A conversation<br>is a good beginning.</h2><div class="contact-card"><h3>Call FBS</h3><a class="large-link" href="tel:+353830441400">{e(S['phone'])}</a></div><div class="contact-card"><h3>Email</h3><a href="mailto:info@fbsflooring.ie">{e(S['email'])}</a></div><div class="contact-card"><h3>Our business address</h3><p>{e(S['address'])}</p><p class="form-note">Contact FBS before travelling to arrange an appointment.</p><a href="https://www.google.com/maps/search/?api=1&query=Unit%20J2%20Malahide%20Road%20Industrial%20Estate%20D17%20FR58" target="_blank" rel="noopener noreferrer">View location on Google Maps ↗</a></div><div class="contact-card"><h3>Not measured yet?</h3><p>You can still get in touch. Approximate dimensions and room photos are helpful starting points.</p>{textlink('Estimate your room area','/flooring-planner/')}</div></section><section class="quote-form" id="quote"><h2>Tell us what you’re planning.</h2><p>Start with a few details. FBS will need to agree the appointment and project scope with you.</p><form id="quote-form"><div class="form-grid"><label class="field">Your name<input name="name" autocomplete="name" maxlength="100" required></label><label class="field">Email address<input name="email" type="email" autocomplete="email" maxlength="150" required></label><label class="field">Phone (optional)<input name="phone" type="tel" autocomplete="tel" maxlength="40"></label><label class="field">Town or Eircode<input name="location" autocomplete="postal-code" maxlength="100" required placeholder="Where is the project?"></label><label class="field full">How can we help?<select name="service"><option value="home-consultation">Free home consultation</option><option value="floor-fitting">Professional floor fitting</option><option value="new-homes-renovations">New home or renovation project</option><option value="commercial">Commercial fitting enquiry</option><option value="advice">Not sure yet — advice</option></select></label><label class="field">Your project<select name="project"><option>Updating an existing room</option><option>Renovating a home</option><option>Moving into a new home</option><option>Business premises</option></select></label><label class="field">Approximate area (m²)<input name="area" type="number" min="0.1" max="10000" step="0.01" placeholder="Optional"></label><label class="field full">Preferred timing<input name="timing" maxlength="150" placeholder="A planned date, or just exploring"></label><label class="field full">Anything else we should know?<textarea name="message" maxlength="3000" placeholder="Which rooms? Do you already have flooring? Any details you want to discuss?"></textarea></label></div><p class="form-note">Prepare your message here, then review and send it in your email app or WhatsApp. Nothing is sent when you press this button. <a href="/privacy-policy/">Privacy information</a></p><button class="button" type="submit">Prepare my enquiry {ARROW}</button><div class="quote-summary" id="quote-summary" hidden aria-live="polite"><h3>Your message is ready.</h3><pre id="quote-preview"></pre><div class="actions"><a class="button" id="email-enquiry" href="mailto:info@fbsflooring.ie">Send using email ↗</a><a class="button outline" id="whatsapp-enquiry" href="https://wa.me/353830441400" target="_blank" rel="noopener noreferrer">Send using WhatsApp ↗</a><button class="text-button" id="copy-enquiry" type="button">Copy message</button></div><p class="form-note" id="copy-status" role="status">Review the details and press send in the app you choose. Your enquiry has not been sent yet.</p></div></form></section></div></div>'''
write('/contact-us/','Contact FBS — Book a Free Flooring Consultation','Contact FBS Flooring in Coolock, Dublin. Discuss a free home consultation, measurements and professional floor fitting.',contact)
write('/flooring-planner/','Room Area Planner for Your Fitting Enquiry','Estimate rectangular room area in square metres and add the result to your FBS flooring service enquiry.',f'''<div class="wrap">{crumbs('Room area planner')}{heading('A few measurements.<br>A useful <em>starting point.</em>','Estimate the area of a rectangular room before discussing your fitting project.','Room area planner')}<div class="split" style="padding-bottom:80px"><section class="planner-box"><form id="room-planner"><div class="form-grid"><label class="field">Room length (metres)<input name="length" type="number" min="0.1" max="1000" step="0.01" required placeholder="e.g. 5"></label><label class="field">Room width (metres)<input name="width" type="number" min="0.1" max="1000" step="0.01" required placeholder="e.g. 4"></label></div><button class="button" type="submit">Estimate floor area</button></form><div class="planner-result" id="planner-result" hidden aria-live="polite"><strong id="area-total"></strong><p>Estimated rectangular floor area. Confirm the measurements with your fitter.</p><div class="actions"><a id="area-enquiry" class="button" href="/contact-us/#quote">Add to my enquiry ↗</a></div></div></section><section class="split-copy"><h2>Measure. Note.<br>Discuss.</h2><p>Multiply length by width for a rectangular room. For an irregular room, sketch smaller rectangles and add their areas without overlapping them.</p><p>This estimate helps describe your project. The final area, preparation and fitting requirements need to be reviewed by the team.</p><p class="form-note">No prices, product quantities or material orders are calculated here.</p><div class="actions">{textlink('Read the measuring guide','/how-to-measure-your-room-for-flooring/')}</div></section></div></div>''')
gallery_items=[('hero','Pattern & warmth'),('kitchen','Light & texture'),('home','A calm, open room'),('consultation','A connected living space')]
body=f'<div class="wrap">{crumbs("Interior inspiration")}{heading("A feeling for<br><em>your space.</em>","Look at the light, pattern and way a floor connects a room. Bring your ideas to a conversation with FBS.","Interior inspiration")}<div class="gallery-grid">'+''.join(f'<button class="gallery-item" data-gallery="{IMAGES[k]["src"]}" data-caption="{e(t)} · Interior inspiration" aria-label="Open {e(t)} image"><div class="gallery-photo">{image(k,t+", illustrative interior imagery")}</div><span>{e(t)} {ARROW}</span></button>' for k,t in gallery_items)+'</div><p class="media-note">Interior and lifestyle imagery originally published on the FBS website. This is an inspiration gallery; the images are not presented as completed FBS jobs or customer case studies.</p></div><dialog class="lightbox" id="gallery-dialog" aria-labelledby="gallery-caption"><div class="lightbox-header"><span id="gallery-caption"></span><button class="icon-button" type="button" id="gallery-close" aria-label="Close image">×</button></div><img id="gallery-image" alt=""></dialog><div style="height:60px"></div>'
write('/gallery/','Interior Inspiration for Your Flooring Project','Interior inspiration from imagery published on the FBS website. Discuss the fitting your own room needs.',body)
blog=f'<div class="wrap">{crumbs("Advice & preparation")}{heading("Good preparation.<br><em>Better conversations.</em>","Useful guides for planning a consultation, measuring your rooms and getting ready for fitting.","The FBS journal")}<div class="blog-tools"><label class="field">Search guides<input id="blog-search" type="search" placeholder="Try measurements or fitting"></label><label class="field">Topic<select id="blog-category"><option value="">All topics</option>'+''.join(f'<option>{e(t)}</option>' for t in sorted({g['category'] for g in GUIDES}))+f'</select></label><p id="blog-count" aria-live="polite">{len(GUIDES)} guides</p></div><div class="cards blog-grid">'+''.join(guide_card(g) for g in GUIDES)+'</div><div id="blog-empty" hidden><h2>No matching guides.</h2><p>Try another search or topic.</p><button id="blog-reset" class="text-button" type="button">Clear filters</button></div></div><div style="height:90px"></div>'
write('/blog/','Flooring Fitting Advice & Preparation Guides','Read practical guides to home consultations, room measurements, fitting preparation and project planning.',blog)
for g in GUIDES:
 body=f'<article class="article">{crumbs(g["category"],("Advice","/blog/"))}<span class="eyebrow" style="margin-top:35px">{e(g["category"])} · 3 minute read</span><h1>{e(g["title"])}</h1><p class="lead">{e(g["summary"])}</p><div class="article-photo">{image(g["image"],"Illustrative flooring planning imagery")}</div>'+''.join(f'<h2>{e(t)}</h2><p>{e(p)}</p>' for t,p in g['sections'])+f'<div class="callout"><h2>Make it about your space.</h2><p>Share your room details with FBS and discuss the consultation or fitting you need.</p><div class="actions">{button("Talk to FBS","/contact-us/#quote")}</div></div><div class="actions">{textlink("Back to all guides","/blog/")}</div></article>'
