policies=[('/privacy-policy/','Privacy information',[('Your enquiry','The enquiry tool runs in your browser. It prepares a message for your email app or WhatsApp. No enquiry is sent to FBS until you review it and send it using the app you choose. The details are passed to that service when you open the prepared message.'),('External services','Email, WhatsApp and Google Maps have their own privacy policies. Links to these services are opened only when you choose them. No map, advertising or social feed is embedded here.'),('Contact','For questions about information you send to FBS, contact info@fbsflooring.ie. For FBS’s wider privacy information, refer to its published privacy policy at fbsflooring.ie/privacy-policy/.')]),('/cookie-policy/','Cookies & site preferences',[('This preview','This website does not include advertising analytics, marketing trackers or saved product lists. The room planner and enquiry builder run in your browser without saving your form details to local storage.'),('Linked services','If you open a linked service such as WhatsApp or Google Maps, that service applies its own cookies and privacy information. Hosting providers may use essential operational technology to deliver the website.')])]
